@push('scripts')<script>(()=>{document.querySelectorAll('.tenant-quote-form').forEach(form=>{const type=form.querySelector('[data-package-type]'),dims=form.querySelector('[data-dimensions]');const sync=()=>{const box=type?.value==='caja';dims.hidden=!box;dims.querySelectorAll('input').forEach(i=>i.required=box)};type?.addEventListener('change',sync);sync();form.querySelectorAll('[data-postal]').forEach(input=>input.addEventListener('change',async()=>{const side=input.dataset.postal,select=form.querySelector(`[data-settlement="${side}"]`);select.disabled=true;try{const r=await fetch(`/codigos-postales/${input.value}`,{headers:{Accept:'application/json'}}),d=await r.json();if(!r.ok)throw new Error(d.message);select.innerHTML='<option value="">Selecciona una colonia</option>'+d.colonias.map(c=>`<option>${c.nombre}</option>`).join('');select.disabled=false;select.required=true;form.querySelector(`[data-location="${side}"]`).textContent=`${d.municipio}, ${d.estado}`}catch(e){select.innerHTML='<option>Catálogo temporalmente no disponible</option>'}}))})})()</script>@endpush
